namespace Unity.UOS.Security
{
	public class EncryptManager
	{
		public static byte[] Sha256(string data)
		{
			byte[] bytes = Encoding.UTF8.GetBytes(data);
			using SHA256 sHA = SHA256.Create();
			return sHA.ComputeHash(bytes);
		}

		public static string HexString(byte[] data)
		{
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < data.Length; i++)
			{
				stringBuilder.Append(data[i].ToString("X2").ToLower());
			}
			return stringBuilder.ToString();
		}

		public static long GetUnixTimeStampSeconds(DateTime dt)
		{
			DateTime dateTime = new DateTime(1970, 1, 1, 0, 0, 0);
			return Convert.ToInt64((dt - dateTime).TotalSeconds);
		}
	}
	public class PersistManager
	{
		private static string _saltForKey;

		private static int blockSize;

		private static int _hashLen;

		static PersistManager()
		{
			blockSize = 128;
			_hashLen = 32;
			byte[] salt = new byte[8] { 25, 36, 77, 51, 43, 14, 75, 93 };
			_saltForKey = Convert.ToBase64String(new Rfc2898DeriveBytes("5b6fcb4aaa0a42acae649eba45a506ec", salt, 1000).GetBytes(blockSize / 8));
		}

		private static string MakeHash(string original)
		{
			using MD5CryptoServiceProvider mD5CryptoServiceProvider = new MD5CryptoServiceProvider();
			byte[] bytes = Encoding.UTF8.GetBytes(original);
			byte[] array = mD5CryptoServiceProvider.ComputeHash(bytes);
			string text = "";
			for (int i = 0; i < array.Length; i++)
			{
				text += array[i].ToString("x2");
			}
			return text;
		}

		private static void SetSecurityValue(string key, string value)
		{
			string text = MakeHash(key + _saltForKey);
			value = EncryptManager.Encrypt(value + MakeHash(value));
			PlayerPrefs.SetString(text, value);
		}

		private static string GetSecurityValue(string key)
		{
			string text = PlayerPrefs.GetString(MakeHash(key + _saltForKey));
			if (string.IsNullOrEmpty(text))
			{
				return string.Empty;
			}
			try
			{
				text = EncryptManager.Decrypt(text);
			}
			catch (Exception ex)
			{
				Debug.Log((object)ex.Message);
			}
			if (_hashLen > text.Length)
			{
				return string.Empty;
			}
			string text2 = text.Substring(0, text.Length - _hashLen);
			string text3 = text.Substring(text.Length - _hashLen);
			if (MakeHash(text2) != text3)
			{
				return string.Empty;
			}
			return text2;
		}

		public static void DeleteKey(string key)
		{
			PlayerPrefs.DeleteKey(MakeHash(key + _saltForKey));
		}

		public static void DeleteAll()
		{
			PlayerPrefs.DeleteAll();
		}

		public static void Save()
		{
			PlayerPrefs.Save();
		}

		public static void SetInt(string key, int value)
		{
			SetSecurityValue(key, value.ToString());
		}

		public static void SetLong(string key, long value)
		{
			SetSecurityValue(key, value.ToString());
		}

		public static void SetFloat(string key, float value)
		{
			SetSecurityValue(key, value.ToString());
		}

		public static void SetString(string key, string value)
		{
			SetSecurityValue(key, value);
		}

		public static int GetInt(string key, int defaultValue)
		{
			string securityValue = GetSecurityValue(key);
			if (string.IsNullOrEmpty(securityValue))
			{
				return defaultValue;
			}
			int result = defaultValue;
			if (!int.TryParse(securityValue, out result))
			{
				return defaultValue;
			}
			return result;
		}

		public static long GetLong(string key, long defaultValue)
		{
			string securityValue = GetSecurityValue(key);
			if (string.IsNullOrEmpty(securityValue))
			{
				return defaultValue;
			}
			long result = defaultValue;
			if (!long.TryParse(securityValue, out result))
			{
				return defaultValue;
			}
			return result;
		}

		public static float GetFloat(string key, float defaultValue)
		{
			string securityValue = GetSecurityValue(key);
			if (string.IsNullOrEmpty(securityValue))
			{
				return defaultValue;
			}
			float result = defaultValue;
			if (!float.TryParse(securityValue, out result))
			{
				return defaultValue;
			}
			return result;
		}

		public static string GetString(string key, string defaultValue)
		{
			string securityValue = GetSecurityValue(key);
			if (string.IsNullOrEmpty(securityValue))
			{
				return defaultValue;
			}
			return securityValue;
		}
	}
