namespace Unity.UOS.Networking
{
	public class AuthenticatorBase
	{
		protected readonly Dictionary<string, string> _headers = new Dictionary<string, string>();

		protected AuthenticatorBase()
		{
		}

		public virtual System.Threading.Tasks.Task ConfigureAuth(UnityWebRequest request)
		{
			foreach (KeyValuePair<string, string> header in _headers)
			{
				request.SetRequestHeader(header.Key, header.Value);
			}
			return System.Threading.Tasks.Task.CompletedTask;
		}
	}
	public class HttpBasicAuthenticator : AuthenticatorBase
	{
		public HttpBasicAuthenticator(string username, string password)
		{
			string value = "Basic " + Convert.ToBase64String(Encoding.GetEncoding(28591).GetBytes(username + ":" + password));
			_headers.Add("Authorization", value);
		}
	}
	public class JwtAuthenticator : AuthenticatorBase
	{
		private readonly string _appID;

		private string _appSecret;

		private readonly NonceTokenAuthenticator _nonceTokenAuthenticator;

		public JwtAuthenticator()
		{
		}

		public JwtAuthenticator(string appID, string appSecret)
		{
			_appID = appID;
			_appSecret = appSecret;
			_nonceTokenAuthenticator = new NonceTokenAuthenticator(appID, appSecret);
		}

		public override async System.Threading.Tasks.Task ConfigureAuth(UnityWebRequest request)
		{
			request.SetRequestHeader("Authorization", "Bearer " + await AuthTokenManager.GetAccessToken(_appID));
			if (_nonceTokenAuthenticator != null)
			{
				await _nonceTokenAuthenticator.ConfigureAuth(request);
			}
		}
	}
	public class NonceTokenAuthenticator : AuthenticatorBase
	{
		public string UosAppID { get; set; }

		public string UosAppSecret { get; set; }

		public NonceTokenAuthenticator(string appID, string appSecret)
		{
			UosAppID = appID;
			UosAppSecret = appSecret;
		}

		public override async System.Threading.Tasks.Task ConfigureAuth(UnityWebRequest request)
		{
			string text = Guid.NewGuid().ToString();
			long unixTimeStampSeconds = EncryptManager.GetUnixTimeStampSeconds(DateTime.UtcNow);
			string text2 = EncryptManager.HexString(EncryptManager.Sha256(string.Format("{0}:{1}:{2}:{3}", new object[4] { UosAppID, UosAppSecret, unixTimeStampSeconds, text })));
			request.SetRequestHeader("X-Timestamp", $"{unixTimeStampSeconds}");
			request.SetRequestHeader("X-Nonce", text);
			request.SetRequestHeader("X-Nonce-Token", text2);
			request.SetRequestHeader("X-AppID", UosAppID);
		}
	}
	public class UosNonceAuthenticator : AuthenticatorBase
	{
		public string UosAppID { get; set; }

		public string UosAppSecret { get; set; }

		public UosNonceAuthenticator(string appID, string appSecret)
		{
			UosAppID = appID;
			UosAppSecret = appSecret;
		}

		public override System.Threading.Tasks.Task ConfigureAuth(UnityWebRequest request)
		{
			string text = Guid.NewGuid().ToString();
			long unixTimeStampSeconds = EncryptManager.GetUnixTimeStampSeconds(DateTime.UtcNow);
			string text2 = EncryptManager.HexString(EncryptManager.Sha256(string.Format("{0}:{1}:{2}:{3}", new object[4] { UosAppID, UosAppSecret, unixTimeStampSeconds, text })));
			request.SetRequestHeader("X-Timestamp", $"{unixTimeStampSeconds}");
			request.SetRequestHeader("X-Nonce", text);
			request.SetRequestHeader("X-AppID", UosAppID);
			request.SetRequestHeader("Authorization", "nonce " + text2);
			return System.Threading.Tasks.Task.CompletedTask;
		}
	}
