		private string ConstructUrl(string url, Dictionary<string, object> queryParams)
		{
			string text = url;
			if (_options.BaseUrl != null)
			{
				text = new Uri(_options.BaseUrl, url).ToString();
			}
			if (queryParams != null)
			{
				string text2 = string.Join("&", queryParams.Where((KeyValuePair<string, object> kv) => kv.Value != null).Select((KeyValuePair<string, object> kv) =>
				{
					if (!kv.Value.GetType().IsArray)
					{
						return kv.Key + "=" + Uri.EscapeDataString(kv.Value.ToString());
					}
					return (!(kv.Value is IEnumerable source)) ? "" : string.Join("&", from object value in source
						select kv.Key + "=" + Uri.EscapeDataString(value.ToString()));
				}));
				text = text + "?" + text2;
			}
			return text;
		}
