	[DisallowMultipleComponent]
	public class InsightSDK : MonoBehaviour
	{
		private static bool _initialized;

		private static bool _enabled;

		private static readonly Queue<Action> _operationCache = new Queue<Action>();

		private static InsightSDK _instance;

		public const string LIB_NAME = "UOS Insight";

		public const string LIB_VERSION = "0.0.1";

		private static bool isLoggedIn;

		public static event Action OnApplicationQuitCallback;

		private void Awake()
		{
			if ((Object)(object)_instance == (Object)null)
			{
				_instance = this;
				Object.DontDestroyOnLoad((Object)(object)((Component)this).gameObject);
				((MonoBehaviour)this).StartCoroutine(InitializeCoroutine());
				OnApplicationQuitCallback += Logout;
			}
			else
			{
				Object.Destroy((Object)(object)((Component)this).gameObject);
			}
		}

		public static void Initialize()
		{
			//IL_0027: Unknown result type (might be due to invalid IL or missing references)
			if (!_initialized)
			{
				TransportClient.Initialize();
				new GameObject("UOSInsight", new Type[1] { typeof(InsightSDK) });
				Log.EnableLog(enabled: false);
			}
		}

		private static IEnumerator InitializeCoroutine()
		{
			Task<bool> task = checkInsightServiceEnabled();
			while (!task.IsCompleted)
			{
				yield return null;
			}
			if (!task.Result)
			{
				_initialized = true;
				_enabled = false;
				_operationCache.Clear();
				yield break;
			}
			_enabled = true;
			InitService(new DataAnalyticsConfig(Settings.AppID));
			System.Threading.Tasks.Task adIdTask = GetDeviceAdvertisingId();
			while (!adIdTask.IsCompleted)
			{
				yield return null;
			}
			FlushEventCaches();
		}

		private static async Task<bool> checkInsightServiceEnabled()
		{
			try
			{
				await TransportClient.GetProject();
				return true;
			}
			catch (Exception ex)
			{
				if (Log.GetEnable())
				{
					Log.e("Get service status failed : " + ex.Message);
				}
			}
			return false;
		}

		private static void InitService(DataAnalyticsConfig config)
		{
			_initialized = true;
			try
			{
				if (string.IsNullOrEmpty(config.appId))
				{
					return;
				}
				config.appId = config.appId.Replace(" ", "");
				InsightConfig instance = InsightConfig.GetInstance(config.appId, config.name);
				if (!string.IsNullOrEmpty(config.getTimeZoneId()))
				{
					try
					{
						instance.SetTimeZone(TimeZoneInfo.FindSystemTimeZoneById(config.getTimeZoneId()));
					}
					catch (Exception ex)
					{
						if (Log.GetEnable())
						{
							Log.e("TimeZoneInfo set failed : " + ex.Message);
						}
					}
				}
				AnalyticsService.Init(config.appId, config.name, instance, (MonoBehaviour)(object)_instance);
				if (Log.GetEnable())
				{
					Log.i(string.Format("Insight SDK initialize success, AppId = {0}, TimeZone = {1}, DeviceId = {2}, Lib = Unity, LibVersion = {3}{4}", new object[5]
					{
						config.appId,
						config.timeZone,
						AnalyticsService.GetDeviceId(),
						"0.0.1",
						(config.name != null) ? (", Name = " + config.name) : ""
					}));
				}
			}
			catch (Exception ex2)
			{
				if (Log.GetEnable())
				{
					Log.i("Insight start Error: " + ex2.Message);
				}
			}
		}

		public static void EnableAutoReport(AutoReportEventType eventType, Dictionary<string, object> properties = null)
		{
			//IL_006e: Unknown result type (might be due to invalid IL or missing references)
			if (!_initialized)
			{
				_operationCache.Enqueue(() =>
				{
					EnableAutoReport(eventType, properties);
				});
			}
			else if (_enabled)
			{
				if (properties == null)
				{
					properties = new Dictionary<string, object>();
				}
				AnalyticsService.EnableAutoReport(eventType, properties);
				if ((eventType & AutoReportEventType.AppSceneLoad) != 0)
				{
					ReportSceneLoad(SceneManager.GetActiveScene());
				}
				if ((eventType & AutoReportEventType.AppCrash) != 0)
				{
					ExceptionHandler.RegisterExceptionHandler(properties);
				}
				if ((eventType & AutoReportEventType.AppSceneLoad) != 0)
				{
					SceneManager.sceneLoaded -= OnSceneLoaded;
					SceneManager.sceneLoaded += OnSceneLoaded;
				}
				if ((eventType & AutoReportEventType.AppSceneUnload) != 0)
				{
					SceneManager.sceneUnloaded -= OnSceneUnloaded;
					SceneManager.sceneUnloaded += OnSceneUnloaded;
				}
			}
		}

