		public static void ReportEvent(string eventName, Dictionary<string, object> properties = null, DateTime? eventTime = null)
		{
			if (!_initialized)
			{
				DateTime assignedTime = eventTime ?? DateTime.UtcNow;
				_operationCache.Enqueue(() =>
				{
					if (_enabled)
					{
						AnalyticsService.Report(eventName, properties, assignedTime);
					}
				});
			}
			else if (_enabled)
			{
				AnalyticsService.Report(eventName, properties, eventTime ?? DateTime.UtcNow);
			}
		}

