		private static void ReportSceneLoad(Scene scene)
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>
			{
				{ "#scene_name", scene.name },
				{ "#scene_path", scene.path }
			};
			Dictionary<string, object> dictionary2 = new Dictionary<string, object>(dictionary);
			CommonUtil.AddDictionary(dictionary2, AnalyticsService.GetEventHandler(AutoReportEventType.AppSceneLoad, dictionary));
			AnalyticsService.Report("scene_loaded", dictionary2);
			AnalyticsService.TimeEvent("scene_unloaded");
		}

		private static void ReportSceneUnload(Scene scene)
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>
			{
				{ "#scene_name", scene.name },
				{ "#scene_path", scene.path }
			};
			Dictionary<string, object> dictionary2 = new Dictionary<string, object>(dictionary);
			CommonUtil.AddDictionary(dictionary2, AnalyticsService.GetEventHandler(AutoReportEventType.AppSceneUnload, dictionary));
			if ((AnalyticsService.GetEventType() & AutoReportEventType.AppSceneUnload) != 0)
			{
				AnalyticsService.Report("scene_unloaded", dictionary2);
			}
		}

