		private static void FlushEventCaches()
		{
			Action result;
			while (_operationCache.TryDequeue(out result))
			{
				result();
			}
		}

		public static void SetAccount(string account)
		{
			if (!_initialized)
			{
				_operationCache.Enqueue(() =>
				{
					SetAccount(account);
				});
			}
			else if (_enabled && !isLoggedIn)
			{
				AnalyticsService.Login(account);
			}
		}

		public static void Login(string account)
		{
			if (!_initialized)
			{
				_operationCache.Enqueue(() =>
				{
					Login(account);
				});
			}
			else if (_enabled)
			{
				if (!string.IsNullOrEmpty(AnalyticsService.AccountID()))
				{
					AnalyticsService.Report("logout");
					Flush();
				}
				AnalyticsService.Login(account);
				if (!string.IsNullOrEmpty(account))
				{
					AnalyticsService.Report("login");
				}
				isLoggedIn = true;
			}
		}

		public static void Logout()
		{
			if (!_initialized)
			{
				_operationCache.Enqueue(Logout);
			}
			else if (_enabled && isLoggedIn)
			{
				if (!string.IsNullOrEmpty(AnalyticsService.AccountID()))
				{
					AnalyticsService.Report("logout");
					Flush();
				}
				AnalyticsService.Logout();
			}
		}

