				AnalyticsTimeZone.Asia_Shanghai => "Asia/Shanghai", 
				AnalyticsTimeZone.Asia_Tokyo => "Asia/Tokyo", 
				AnalyticsTimeZone.America_Los_Angeles => "America/Los_Angeles", 
				AnalyticsTimeZone.America_New_York => "America/New_York", 
				AnalyticsTimeZone.Other => timeZoneId, 
				_ => null, 
			};
		}
