namespace Unity.UOS.Insight.Wrapper
{
	public class BaseWrapper
	{
		public class OAIDCallbackListener : AndroidJavaProxy
		{
			public OAIDCallbackListener()
				: base("com.github.gzuliyujiang.oaid.IGetter")
			{
			}

			private void onOAIDGetComplete(string result)
			{
				Debug.Log((object)("Get OAID Complete: " + result + "\n"));
				_oaidTcs?.TrySetResult(result);
			}

			private void onOAIDGetError(AndroidJavaObject error)
			{
				Debug.Log((object)("Get OAID Error:" + ((object)error)?.ToString() + "\n"));
				_oaidTcs?.TrySetException(new Exception("Failed to fetch OAID: " + (object)error));
			}
		}

		private static TaskCompletionSource<string> _oaidTcs;

		public static async Task<string> FetchOAIDAsync()
		{
			_oaidTcs = new TaskCompletionSource<string>();
			AndroidJavaObject val = ((AndroidJavaObject)new AndroidJavaClass("com.unity3d.player.UnityPlayer")).GetStatic<AndroidJavaObject>("currentActivity");
			((AndroidJavaObject)new AndroidJavaClass("com.github.gzuliyujiang.oaid.DeviceID")).CallStatic("getOAID", new object[2]
			{
				val,
				new OAIDCallbackListener()
			});
			return await _oaidTcs.Task;
		}
	}
