		private static Dictionary<string, object> deviceInfo;

		public static bool IsValidURL(string url)
		{
			if (!string.IsNullOrEmpty(url) && url.Contains("http"))
			{
				return url.Contains("https");
			}
			return false;
		}

		public static bool IsEmptyString(string str)
		{
			return string.IsNullOrEmpty(str);
		}

		public static Dictionary<string, object> GetDeviceInfo()
		{
			if (deviceInfo == null)
			{
				deviceInfo = new Dictionary<string, object>();
				deviceInfo["#device_id"] = DeviceInfo.DeviceID();
				deviceInfo["#os"] = DeviceInfo.OS();
				deviceInfo["#os_version"] = DeviceInfo.OSVersion();
				deviceInfo["#screen_height"] = DeviceInfo.ScreenHeight();
				deviceInfo["#screen_width"] = DeviceInfo.ScreenWidth();
				deviceInfo["#manufacturer"] = DeviceInfo.Manufacture();
				deviceInfo["#device_model"] = DeviceInfo.DeviceModel();
				deviceInfo["#app_version"] = GeneralInfo.AppVersion();
				deviceInfo["#bundle_id"] = GeneralInfo.AppIdentifier();
				deviceInfo["#lib"] = GeneralInfo.LibName();
				deviceInfo["#lib_version"] = GeneralInfo.LibVersion();
			}
			deviceInfo["#system_language"] = DeviceInfo.MachineLanguage();
			deviceInfo["#network_type"] = DeviceInfo.NetworkType();
			return deviceInfo;
		}

		public static string RandomID(bool persistent = true)
		{
			string text = null;
			if (persistent)
			{
				text = (string)File.GetData("RANDDOM_ID", typeof(string));
			}
			if (string.IsNullOrEmpty(text))
			{
				text = Guid.NewGuid().ToString("N");
				if (persistent)
				{
					File.SaveData("RANDDOM_ID", text);
				}
			}
			return text;
		}

		public static double ZoneOffset(DateTime dateTime, TimeZoneInfo timeZone)
		{
			return timeZone.BaseUtcOffset.TotalHours;
		}

		public static void AddDictionary(Dictionary<string, object> originalDic, Dictionary<string, object> subDic)
		{
			if (originalDic == subDic)
			{
				return;
			}
			foreach (KeyValuePair<string, object> item in subDic)
			{
				originalDic[item.Key] = item.Value;
			}
		}

		public static long GetTimeStamp()
		{
			return Convert.ToInt64((DateTime.UtcNow - new DateTime(1970, 1, 1, 0, 0, 0, 0)).TotalMilliseconds);
		}

		public static string FormatDate(DateTime dateTime, TimeZoneInfo timeZone)
		{
			return TimeZoneInfo.ConvertTime(dateTime, timeZone).ToString("O", CultureInfo.InvariantCulture);
		}
	}
