	public class File
	{
		private static string connectorKey = "_";

		public static string GetKey(string prefix, string key)
		{
			return prefix + connectorKey + key;
		}

		public static void SaveData(string prefix, string key, object value)
		{
			SaveData(GetKey(prefix, key), value);
		}

		public static void SaveData(string key, object value)
		{
			if (!string.IsNullOrEmpty(key))
			{
				if (value.GetType() == typeof(int))
				{
					PlayerPrefs.SetInt(key, (int)value);
				}
				else if (value.GetType() == typeof(float))
				{
					PlayerPrefs.SetFloat(key, (float)value);
				}
				else if (value.GetType() == typeof(string))
				{
					PlayerPrefs.SetString(key, (string)value);
				}
				PlayerPrefs.Save();
			}
		}

		public static object GetData(string key, Type type)
		{
			if (!string.IsNullOrEmpty(key) && PlayerPrefs.HasKey(key))
			{
				if (type == typeof(int))
				{
					return PlayerPrefs.GetInt(key);
				}
				if (type == typeof(float))
				{
					return PlayerPrefs.GetFloat(key);
				}
				if (type == typeof(string))
				{
					return PlayerPrefs.GetString(key);
				}
				PlayerPrefs.Save();
			}
			return null;
		}

		public static object GetData(string prefix, string key, Type type)
		{
			key = GetKey(prefix, key);
			return GetData(key, type);
		}

		public static void DeleteData(string key)
		{
			if (!string.IsNullOrEmpty(key) && PlayerPrefs.HasKey(key))
			{
				PlayerPrefs.DeleteKey(key);
			}
		}

		public static void DeleteData(string prefix, string key)
		{
			key = GetKey(prefix, key);
			DeleteData(key);
		}
	}
	public class FileJson
	{
		private static string eventKeyInfix = "Event";

		private static string eventIndexIDSuffix = "EventIndexID";

		private static string eventAutoIncrementingIDSuffix = "EventAutoIncrementingID";

		private static string eventBatchPrefix = "[";

		private static string eventBatchInfix = ",";

		private static string eventBatchSuffix = "]";

		private static Dictionary<string, string> eventKeysPrefix = new Dictionary<string, string>();

		private static Dictionary<string, string> eventIndexIDKeys = new Dictionary<string, string>();

		private static Dictionary<string, string> eventAutoIncrementingIDKeys = new Dictionary<string, string>();

		internal static int EnqueueReportingData(Dictionary<string, object> data, string prefix)
		{
			int index = EventAutoIncrementingID(prefix);
			string text = GetEventKeysPrefix(prefix, index);
			string text2 = MiniJson.Serialize(data);
			PlayerPrefs.SetString(text, text2);
			IncreaseReportingDataID(prefix);
			return EventAutoIncrementingID(prefix) - EventIndexID(prefix);
		}

		internal static int EventAutoIncrementingID(string prefix)
		{
			string eventAutoIncrementingIDKey = GetEventAutoIncrementingIDKey(prefix);
			if (!PlayerPrefs.HasKey(eventAutoIncrementingIDKey))
			{
				return 0;
			}
			return PlayerPrefs.GetInt(eventAutoIncrementingIDKey);
		}

		private static void IncreaseReportingDataID(string prefix)
		{
			int num = EventAutoIncrementingID(prefix);
			num++;
			PlayerPrefs.SetInt(GetEventAutoIncrementingIDKey(prefix), num);
		}

		private static void ResetReportingDataID(string prefix)
		{
			int num = 0;
			PlayerPrefs.SetInt(GetEventAutoIncrementingIDKey(prefix), num);
		}

		internal static int EventIndexID(string prefix)
		{
			string eventIndexIDKey = GetEventIndexIDKey(prefix);
			if (!PlayerPrefs.HasKey(eventIndexIDKey))
			{
				return 0;
			}
			return PlayerPrefs.GetInt(eventIndexIDKey);
		}

		private static void SaveEventIndexID(int indexID, string prefix)
		{
			PlayerPrefs.SetInt(GetEventIndexIDKey(prefix), indexID);
		}

		internal static string DequeueBatchReportingData(int batchSize, string prefix, out int eventCount)
		{
			string text = eventBatchPrefix;
			new List<Dictionary<string, object>>();
			int num = EventIndexID(prefix);
			int num2 = EventAutoIncrementingID(prefix) - 1;
			eventCount = 0;
			while (eventCount < batchSize && num <= num2)
			{
				string text2 = GetEventKeysPrefix(prefix, num);
				if (PlayerPrefs.HasKey(text2))
				{
					string text3 = PlayerPrefs.GetString(text2);
					text = ((eventCount >= batchSize - 1 || num >= num2) ? (text + text3) : (text + text3 + eventBatchInfix));
					eventCount++;
				}
				num++;
			}
			if (eventCount > 0)
			{
				return text + eventBatchSuffix;
			}
			return null;
		}

		internal static int DeleteBatchReportingData(int batchSize, string prefix)
		{
			int num = 0;
			int num2 = EventIndexID(prefix);
			int num3 = EventAutoIncrementingID(prefix) - 1;
			while (num < batchSize && num2 <= num3)
			{
				string text = GetEventKeysPrefix(prefix, num2);
				if (PlayerPrefs.HasKey(text))
				{
					PlayerPrefs.DeleteKey(text);
					num++;
				}
				num2++;
			}
			SaveEventIndexID(num2, prefix);
			return EventAutoIncrementingID(prefix) - EventIndexID(prefix);
		}

		internal static int DeleteAllReportingData(string prefix)
		{
			DeleteBatchReportingData(int.MaxValue, prefix);
			SaveEventIndexID(0, prefix);
			ResetReportingDataID(prefix);
			return 0;
		}

		private static string GetEventKeysPrefix(string prefix, int index)
		{
			if (eventKeysPrefix.ContainsKey(prefix))
			{
				return eventKeysPrefix[prefix] + index;
			}
			string text = prefix + eventKeyInfix;
			eventKeysPrefix[prefix] = text;
			return text + index;
		}

		private static string GetEventIndexIDKey(string prefix)
		{
			if (eventIndexIDKeys.ContainsKey(prefix))
			{
				return eventIndexIDKeys[prefix];
			}
			string text = prefix + eventIndexIDSuffix;
			eventIndexIDKeys[prefix] = text;
			return text;
		}

		private static string GetEventAutoIncrementingIDKey(string prefix)
		{
			if (eventAutoIncrementingIDKeys.ContainsKey(prefix))
			{
				return eventAutoIncrementingIDKeys[prefix];
			}
			string text = prefix + eventAutoIncrementingIDSuffix;
			eventAutoIncrementingIDKeys[prefix] = text;
			return text;
		}
	}
