	public class MiniJson
	{
		private sealed class Parser : IDisposable
		{
			private enum TOKEN
			{
				NONE,
				CURLY_OPEN,
				CURLY_CLOSE,
				SQUARED_OPEN,
				SQUARED_CLOSE,
				COLON,
				COMMA,
				STRING,
				NUMBER,
				TRUE,
				FALSE,
				NULL
			}

			private const string WORD_BREAK = "{}[],:\"";

			private StringReader json;

			private char PeekChar => Convert.ToChar(json.Peek());

			private char NextChar => Convert.ToChar(json.Read());

			private string NextWord
			{
				get
				{
					StringBuilder stringBuilder = new StringBuilder();
					while (!IsWordBreak(PeekChar))
					{
						stringBuilder.Append(NextChar);
						if (json.Peek() == -1)
						{
							break;
						}
					}
					return stringBuilder.ToString();
				}
			}

			private TOKEN NextToken
			{
				get
				{
					EatWhitespace();
					if (json.Peek() == -1)
					{
						return TOKEN.NONE;
					}
					switch (PeekChar)
					{
					case '{':
						return TOKEN.CURLY_OPEN;
					case '}':
						json.Read();
						return TOKEN.CURLY_CLOSE;
					case '[':
						return TOKEN.SQUARED_OPEN;
					case ']':
						json.Read();
						return TOKEN.SQUARED_CLOSE;
					case ',':
						json.Read();
						return TOKEN.COMMA;
					case '"':
						return TOKEN.STRING;
					case ':':
						return TOKEN.COLON;
					case '-':
					case '0':
					case '1':
					case '2':
					case '3':
					case '4':
					case '5':
					case '6':
					case '7':
					case '8':
					case '9':
						return TOKEN.NUMBER;
					default:
						return NextWord switch
						{
							"false" => TOKEN.FALSE, 
							"true" => TOKEN.TRUE, 
							"null" => TOKEN.NULL, 
							_ => TOKEN.NONE, 
						};
					}
				}
			}

			public static bool IsWordBreak(char c)
			{
				if (!char.IsWhiteSpace(c))
				{
					return "{}[],:\"".IndexOf(c) != -1;
				}
				return true;
			}

			private Parser(string jsonString)
			{
				json = new StringReader(jsonString);
			}

			public static Dictionary<string, object> Parse(string jsonString)
			{
				using Parser parser = new Parser(jsonString);
				return parser.ParseObject();
			}

			public void Dispose()
			{
				json.Dispose();
				json = null;
			}

			private Dictionary<string, object> ParseObject()
			{
				Dictionary<string, object> dictionary = new Dictionary<string, object>();
				json.Read();
				while (true)
				{
					switch (NextToken)
					{
					case TOKEN.COMMA:
						continue;
					case TOKEN.NONE:
						return null;
					case TOKEN.CURLY_CLOSE:
						return dictionary;
					}
					string text = ParseString();
					if (text == null)
					{
						return null;
					}
					if (NextToken != TOKEN.COLON)
					{
						return null;
					}
					json.Read();
					dictionary[text] = ParseValue();
				}
			}

			private List<object> ParseArray()
			{
				List<object> list = new List<object>();
				json.Read();
				bool flag = true;
				while (flag)
				{
					TOKEN nextToken = NextToken;
					switch (nextToken)
					{
					case TOKEN.NONE:
						return null;
					case TOKEN.SQUARED_CLOSE:
						flag = false;
						break;
					default:
					{
						object item = ParseByToken(nextToken);
						list.Add(item);
						break;
					}
					case TOKEN.COMMA:
						break;
					}
				}
				return list;
			}

			private object ParseValue()
			{
				TOKEN nextToken = NextToken;
				return ParseByToken(nextToken);
			}

			private object ParseByToken(TOKEN token)
			{
				switch (token)
				{
				case TOKEN.STRING:
				{
					string text = ParseString();
					if (DateTime.TryParseExact(text, "yyyy-MM-dd HH:mm:ss.fff", CultureInfo.InvariantCulture, DateTimeStyles.None, out var result))
					{
						return result;
					}
					return text;
				}
				case TOKEN.NUMBER:
					return ParseNumber();
				case TOKEN.CURLY_OPEN:
					return ParseObject();
				case TOKEN.SQUARED_OPEN:
					return ParseArray();
				case TOKEN.TRUE:
					return true;
				case TOKEN.FALSE:
					return false;
				case TOKEN.NULL:
					return null;
				default:
					return null;
				}
			}

			private string ParseString()
			{
				StringBuilder stringBuilder = new StringBuilder();
				json.Read();
				bool flag = true;
				while (flag)
				{
					if (json.Peek() == -1)
					{
						flag = false;
						break;
					}
					char nextChar = NextChar;
					switch (nextChar)
					{
					case '"':
						flag = false;
						break;
					case '\\':
						if (json.Peek() == -1)
						{
							flag = false;
							break;
						}
						nextChar = NextChar;
						switch (nextChar)
						{
						case '"':
						case '/':
						case '\\':
							stringBuilder.Append(nextChar);
							break;
						case 'b':
							stringBuilder.Append('\b');
							break;
						case 'f':
							stringBuilder.Append('\f');
							break;
						case 'n':
							stringBuilder.Append('\n');
							break;
						case 'r':
							stringBuilder.Append('\r');
							break;
						case 't':
							stringBuilder.Append('\t');
							break;
						case 'u':
						{
							char[] array = new char[4];
							for (int i = 0; i < 4; i++)
							{
								array[i] = NextChar;
							}
							stringBuilder.Append((char)Convert.ToInt32(new string(array), 16));
							break;
						}
						}
						break;
					default:
						stringBuilder.Append(nextChar);
						break;
					}
				}
				return stringBuilder.ToString();
			}

			private object ParseNumber()
			{
				string nextWord = NextWord;
				if (nextWord.IndexOf('.') == -1 && nextWord.IndexOf('E') == -1 && nextWord.IndexOf('e') == -1)
				{
					long.TryParse(nextWord, NumberStyles.Any, CultureInfo.InvariantCulture, out var result);
					return result;
				}
				if (!double.TryParse(nextWord, NumberStyles.Any, CultureInfo.InvariantCulture, out var result2))
				{
					double.TryParse(nextWord, NumberStyles.Any, CultureInfo.CreateSpecificCulture("es-ES"), out result2);
				}
				return result2;
			}

			private void EatWhitespace()
			{
				while (char.IsWhiteSpace(PeekChar))
				{
					json.Read();
					if (json.Peek() == -1)
					{
						break;
					}
				}
			}
		}

		private sealed class Serializer
		{
			private StringBuilder builder;

			private Func<DateTime, string> func;

			private Serializer()
			{
				builder = new StringBuilder();
			}

			public static string Serialize(object obj, Func<DateTime, string> func)
			{
				Serializer serializer = new Serializer();
				serializer.func = func;
				serializer.SerializeValue(obj);
				return serializer.builder.ToString();
			}

			private void SerializeValue(object value)
			{
				if (value == null)
				{
					builder.Append("null");
				}
				else if (value is string str)
				{
					SerializeString(str);
				}
				else if (value is bool)
				{
					builder.Append(((bool)value) ? "true" : "false");
				}
				else if (value is IList anArray)
				{
					SerializeArray(anArray);
				}
				else if (value is IDictionary obj)
				{
					SerializeObject(obj);
				}
				else if (value is char)
				{
					SerializeString(new string((char)value, 1));
				}
				else
				{
					SerializeOther(value);
				}
			}

			private void SerializeObject(IDictionary obj)
			{
				bool flag = true;
				builder.Append('{');
				foreach (object key in obj.Keys)
				{
					if (!flag)
					{
						builder.Append(',');
					}
					SerializeString(key.ToString());
					builder.Append(':');
					SerializeValue(obj[key]);
					flag = false;
				}
				builder.Append('}');
			}

			private void SerializeArray(IList anArray)
			{
				builder.Append('[');
				bool flag = true;
				foreach (object item in anArray)
				{
					if (!flag)
					{
						builder.Append(',');
					}
					SerializeValue(item);
					flag = false;
				}
				builder.Append(']');
			}

			private void SerializeString(string str)
			{
				builder.Append('"');
				char[] array = str.ToCharArray();
				foreach (char c in array)
				{
					switch (c)
					{
					case '"':
						builder.Append("\\\"");
						continue;
					case '\\':
						builder.Append("\\\\");
						continue;
					case '\b':
						builder.Append("\\b");
						continue;
					case '\f':
						builder.Append("\\f");
						continue;
					case '\n':
						builder.Append("\\n");
						continue;
					case '\r':
						builder.Append("\\r");
						continue;
					case '\t':
						builder.Append("\\t");
						continue;
					}
					int num = Convert.ToInt32(c);
					if (num >= 32 && num <= 126)
					{
						builder.Append(c);
						continue;
					}
					builder.Append("\\u");
					builder.Append(num.ToString("x4"));
				}
				builder.Append('"');
			}

			private void SerializeOther(object value)
			{
				if (value is float)
				{
					builder.Append(((float)value).ToString("R", CultureInfo.InvariantCulture));
				}
				else if (value is int || value is uint || value is long || value is sbyte || value is byte || value is short || value is ushort || value is ulong)
				{
					builder.Append(value);
				}
				else if (value is double)
				{
					builder.Append(Convert.ToDouble(value).ToString("R", CultureInfo.InvariantCulture));
				}
				else if (value is decimal)
				{
					builder.Append(Convert.ToDecimal(value).ToString("G", CultureInfo.InvariantCulture));
				}
				else if (value is DateTime)
				{
					builder.Append('"');
					DateTime dateTime = (DateTime)value;
					if (func != null)
					{
						builder.Append(func((DateTime)value));
					}
					else
					{
						builder.Append(dateTime.ToString("yyyy-MM-dd HH:mm:ss.fff", CultureInfo.InvariantCulture));
					}
					builder.Append('"');
				}
				else
				{
					SerializeString(value.ToString());
				}
			}
		}

		public static Dictionary<string, object> Deserialize(string json)
		{
			if (json == null)
			{
				return null;
			}
			return Parser.Parse(json);
		}

		public static string Serialize(object obj, Func<DateTime, string> func = null)
		{
			return Serializer.Serialize(obj, func);
		}
	}
	public class PropertiesChecker
	{
		private static readonly Regex keyPattern = new Regex("^[a-zA-Z][a-zA-Z\\d_#]{0,49}$");

		private static readonly List<string> propertyNameWhitelist = new List<string> { "#scene_name", "#scene_path", "#app_crashed_reason" };

		public static bool IsNumeric(object obj)
		{
			if (!(obj is sbyte) && !(obj is byte) && !(obj is short) && !(obj is ushort) && !(obj is int) && !(obj is uint) && !(obj is long) && !(obj is ulong) && !(obj is double) && !(obj is decimal))
			{
				return obj is float;
			}
			return true;
		}

		public static bool IsString(object obj)
		{
			if (obj == null)
			{
				return false;
			}
			return obj is string;
		}

		public static bool IsDictionary(object obj)
		{
			if (obj == null)
			{
				return false;
			}
			if (obj.GetType().IsGenericType)
			{
				return obj.GetType().GetGenericTypeDefinition() == typeof(Dictionary<, >);
			}
			return false;
		}

		public static bool IsList(object obj)
		{
			if (obj == null)
			{
				return false;
			}
			if (!obj.GetType().IsGenericType || !(obj.GetType().GetGenericTypeDefinition() == typeof(List<>)))
			{
				return obj is Array;
			}
			return true;
		}

		public static bool CheckProperties<V>(Dictionary<string, V> properties)
		{
			if (properties == null)
			{
				return true;
			}
			bool result = true;
			foreach (KeyValuePair<string, V> property in properties)
			{
				if (!CheckString(property.Key))
				{
					result = false;
				}
				if (!(property.Value is string) && !(property.Value is DateTime) && !(property.Value is bool) && !IsNumeric(property.Value) && !IsList(property.Value) && !IsDictionary(property.Value))
				{
					if (Log.GetEnable())
					{
						Log.w("Incorrect property - property values must be one of: String, Numberic, Boolean, DateTime, Array, Row");
					}
					result = false;
				}
				if (IsString(property.Value) && !CheckProperties(property.Value as string))
				{
					result = false;
				}
				if (IsNumeric(property.Value) && !CheckProperties(Convert.ToDouble(property.Value)))
				{
					result = false;
				}
				if (IsList(property.Value) && !CheckProperties(property.Value as List<object>))
				{
					result = false;
				}
				if (IsDictionary(property.Value) && !CheckProperties(property.Value as Dictionary<string, object>))
				{
					result = false;
				}
			}
			return result;
		}

		public static bool CheckProperties(List<object> properties)
		{
			if (properties == null)
			{
				return true;
			}
			bool result = true;
			foreach (object property in properties)
			{
				if (!(property is string) && !(property is DateTime) && !(property is bool) && !IsNumeric(property) && !IsDictionary(property))
				{
					if (Log.GetEnable())
					{
						Log.w("Incorrect property - property values in list must be one of: String, Numberic, Boolean, DateTime, Row");
					}
					result = false;
				}
				if (IsString(property) && !CheckProperties(property as string))
				{
					result = false;
				}
				if (IsNumeric(property) && !CheckProperties(Convert.ToDouble(property)))
				{
					result = false;
				}
				if (IsDictionary(property) && !CheckProperties(property as Dictionary<string, object>))
				{
					result = false;
				}
			}
			return result;
		}

		public static bool CheckProperties(List<string> properties)
		{
			if (properties == null)
			{
				return true;
			}
			bool result = true;
			foreach (string property in properties)
			{
				if (!CheckProperties(property))
				{
					result = false;
				}
			}
			return result;
		}

		public static bool CheckProperties(string properties)
		{
			if (properties != null && Encoding.UTF8.GetBytes(Convert.ToString(properties)).Length > 2048)
			{
				if (Log.GetEnable())
				{
					Log.w("Incorrect properties - the string is too long: " + properties);
				}
				return false;
			}
			return true;
		}

		public static bool CheckProperties(double properties)
		{
			if (properties > 9999999999999.998 || properties < -9999999999999.998)
			{
				if (Log.GetEnable())
				{
					Log.w("Incorrect properties - number value is invalid: " + properties + ", the data range is -9E15 to 9E15, with a maximum of 3 decimal places");
				}
				return false;
			}
			return true;
		}

		public static bool CheckString(string eventName)
		{
			if (string.IsNullOrEmpty(eventName))
			{
				if (Log.GetEnable())
				{
					Log.w("Incorrect event name - the string is null");
				}
				return false;
			}
			if (keyPattern.IsMatch(eventName))
			{
				return true;
			}
			if (propertyNameWhitelist.Contains(eventName))
			{
				return true;
			}
			if (Log.GetEnable())
			{
				Log.w("Incorrect event name - the string is invalid for Insight: " + eventName + ", event name and properties name rules: must be character string type, starting with a character and containing figures, characters, and an underline \"_\", with a maximum length of 50 characters");
			}
			return false;
		}

		public static void MergeProperties(Dictionary<string, object> source, Dictionary<string, object> dest)
		{
			if (source == null)
			{
				return;
			}
			foreach (KeyValuePair<string, object> item in source)
			{
				if (dest.ContainsKey(item.Key))
				{
					dest[item.Key] = item.Value;
				}
				else
				{
					dest.Add(item.Key, item.Value);
				}
			}
		}
	}
}
