namespace Unity.UOS.Insight.Service
{
	public class AnalyticsAutoReport : MonoBehaviour
	{
		private string mAppId;

		private AutoReportEventType mAutoReportEvents;

		private bool mStarted;

		private AutoReportEventHandler mEventCallback;

		private Dictionary<string, Dictionary<string, object>> mAutoReportProperties = new Dictionary<string, Dictionary<string, object>>();

		private const string InsightAutoReportEventType_APP_START = "AppStart";

		private const string InsightAutoReportEventType_APP_END = "AppEnd";

		private const string InsightAutoReportEventType_APP_CRASH = "AppCrash";

		private const string InsightAutoReportEventType_APP_INSTALL = "AppInstall";

		private void Start()
		{
		}

		private void OnApplicationFocus(bool hasFocus)
		{
			if (hasFocus)
			{
				if ((mAutoReportEvents & AutoReportEventType.AppStart) != 0)
				{
					Dictionary<string, object> dictionary = new Dictionary<string, object>();
					if (mAutoReportProperties.ContainsKey("AppStart"))
					{
						CommonUtil.AddDictionary(dictionary, mAutoReportProperties["AppStart"]);
					}
					if (mEventCallback != null)
					{
						CommonUtil.AddDictionary(dictionary, mEventCallback.GetAutoReportEventProperties(1, dictionary));
					}
					AnalyticsService.Report("app_start", dictionary, mAppId);
				}
				if ((mAutoReportEvents & AutoReportEventType.AppEnd) != 0)
				{
					AnalyticsService.TimeEvent("app_end", mAppId);
				}
				AnalyticsService.PauseTimeEvent(status: false, "", mAppId);
				return;
			}
			if ((mAutoReportEvents & AutoReportEventType.AppEnd) != 0)
			{
				Dictionary<string, object> dictionary2 = new Dictionary<string, object>();
				if (mAutoReportProperties.ContainsKey("AppEnd"))
				{
					CommonUtil.AddDictionary(dictionary2, mAutoReportProperties["AppEnd"]);
				}
				if (mEventCallback != null)
				{
					CommonUtil.AddDictionary(dictionary2, mEventCallback.GetAutoReportEventProperties(2, dictionary2));
				}
				AnalyticsService.Report("app_end", dictionary2, mAppId);
			}
			AnalyticsService.Flush(mAppId);
			AnalyticsService.PauseTimeEvent(status: true, "", mAppId);
		}

		private void OnApplicationQuit()
		{
			if (Application.isFocused)
			{
				OnApplicationFocus(hasFocus: false);
			}
		}

		public void SetAppId(string appId)
		{
			mAppId = appId;
		}

		public void EnableAutoReport(AutoReportEventType events, Dictionary<string, object> properties, string appId)
		{
			mAutoReportEvents = events;
			SetAutoReportProperties(events, properties);
			if ((events & AutoReportEventType.AppInstall) != 0 && Unity.UOS.Insight.Utils.File.GetData(appId, "is_install", typeof(int)) == null)
			{
				Dictionary<string, object> dictionary = new Dictionary<string, object>(properties);
				Unity.UOS.Insight.Utils.File.SaveData(appId, "is_install", 1);
				if (mAutoReportProperties.ContainsKey("AppInstall"))
				{
					CommonUtil.AddDictionary(dictionary, mAutoReportProperties["AppInstall"]);
				}
				AnalyticsService.Report("app_install", dictionary, mAppId);
				AnalyticsService.Flush(mAppId);
			}
			if ((events & AutoReportEventType.AppStart) != 0 && !mStarted)
			{
				Dictionary<string, object> dictionary2 = new Dictionary<string, object>(properties);
				if (mAutoReportProperties.ContainsKey("AppStart"))
				{
					CommonUtil.AddDictionary(dictionary2, mAutoReportProperties["AppStart"]);
				}
				AnalyticsService.Report("app_start", dictionary2, mAppId);
				AnalyticsService.Flush(mAppId);
			}
			if ((events & AutoReportEventType.AppEnd) != 0 && !mStarted)
			{
				AnalyticsService.TimeEvent("app_end", mAppId);
			}
			mStarted = true;
		}

		public void EnableAutoReport(AutoReportEventType events, AutoReportEventHandler eventCallback, string appId)
		{
			mAutoReportEvents = events;
			mEventCallback = eventCallback;
			if ((events & AutoReportEventType.AppInstall) != 0 && Unity.UOS.Insight.Utils.File.GetData(appId, "is_install", typeof(int)) == null)
			{
				Unity.UOS.Insight.Utils.File.SaveData(appId, "is_install", 1);
				Dictionary<string, object> dictionary = null;
				dictionary = ((!mAutoReportProperties.ContainsKey("AppInstall")) ? new Dictionary<string, object>() : mAutoReportProperties["AppInstall"]);
				if (mEventCallback != null)
				{
					CommonUtil.AddDictionary(dictionary, mEventCallback.GetAutoReportEventProperties(32, dictionary));
				}
				AnalyticsService.Report("app_install", dictionary, mAppId);
				AnalyticsService.Flush(mAppId);
			}
			if ((events & AutoReportEventType.AppStart) != 0 && !mStarted)
			{
				Dictionary<string, object> dictionary2 = null;
				dictionary2 = ((!mAutoReportProperties.ContainsKey("AppStart")) ? new Dictionary<string, object>() : mAutoReportProperties["AppStart"]);
				if (mEventCallback != null)
				{
					CommonUtil.AddDictionary(dictionary2, mEventCallback.GetAutoReportEventProperties(1, dictionary2));
				}
				AnalyticsService.Report("app_start", dictionary2, mAppId);
				AnalyticsService.Flush(mAppId);
			}
			if ((events & AutoReportEventType.AppEnd) != 0 && !mStarted)
			{
				AnalyticsService.TimeEvent("app_end", mAppId);
			}
			mStarted = true;
		}

		public void SetAutoReportProperties(AutoReportEventType events, Dictionary<string, object> properties)
		{
			mAutoReportEvents = events;
			if ((events & AutoReportEventType.AppInstall) != 0)
			{
				if (mAutoReportProperties.ContainsKey("AppInstall"))
				{
					CommonUtil.AddDictionary(mAutoReportProperties["AppInstall"], properties);
				}
				else
				{
					mAutoReportProperties["AppInstall"] = properties;
				}
			}
			if ((events & AutoReportEventType.AppStart) != 0)
			{
				if (mAutoReportProperties.ContainsKey("AppStart"))
				{
					CommonUtil.AddDictionary(mAutoReportProperties["AppStart"], properties);
				}
				else
				{
					mAutoReportProperties["AppStart"] = properties;
				}
			}
			if ((events & AutoReportEventType.AppEnd) != 0)
			{
				if (mAutoReportProperties.ContainsKey("AppEnd"))
				{
					CommonUtil.AddDictionary(mAutoReportProperties["AppEnd"], properties);
				}
				else
				{
					mAutoReportProperties["AppEnd"] = properties;
				}
			}
			if ((events & AutoReportEventType.AppCrash) != 0)
			{
				if (mAutoReportProperties.ContainsKey("AppCrash"))
				{
					CommonUtil.AddDictionary(mAutoReportProperties["AppCrash"], properties);
				}
				else
				{
					mAutoReportProperties["AppCrash"] = properties;
				}
			}
		}

		public Dictionary<string, object> GetEventHandler(AutoReportEventType events, Dictionary<string, object> properties)
		{
			return mEventCallback.GetAutoReportEventProperties((int)events, properties);
		}

		public AutoReportEventType GetEventType()
		{
			return mAutoReportEvents;
		}
	}
	public static class AnalyticsService
	{
		private static readonly Dictionary<string, AnalyticsServiceInstance> Instances = new Dictionary<string, AnalyticsServiceInstance>();

		private static string CurrentAppid;

		private static AnalyticsServiceInstance GetInstance(string appId)
		{
			AnalyticsServiceInstance analyticsServiceInstance = null;
			if (!string.IsNullOrEmpty(appId))
			{
				appId = appId.Replace(" ", "");
				if (Instances.ContainsKey(appId))
				{
					analyticsServiceInstance = Instances[appId];
				}
			}
			if (analyticsServiceInstance == null)
			{
				analyticsServiceInstance = Instances[CurrentAppid];
			}
			return analyticsServiceInstance;
		}

		public static AnalyticsServiceInstance CurrentInstance()
		{
			return Instances[CurrentAppid];
		}

		public static AnalyticsServiceInstance Init(string appId, string instanceName, InsightConfig config = null, MonoBehaviour mono = null)
		{
			if (CommonUtil.IsEmptyString(appId))
			{
				if (Log.GetEnable())
				{
					Log.w("appId is empty");
				}
				return null;
			}
			AnalyticsServiceInstance analyticsServiceInstance = null;
			if (!string.IsNullOrEmpty(instanceName))
			{
				if (Instances.ContainsKey(instanceName))
				{
					analyticsServiceInstance = Instances[instanceName];
				}
				else
				{
					analyticsServiceInstance = new AnalyticsServiceInstance(appId, instanceName, config, mono);
					if (string.IsNullOrEmpty(CurrentAppid))
					{
						CurrentAppid = instanceName;
					}
					Instances[instanceName] = analyticsServiceInstance;
				}
			}
			else if (Instances.ContainsKey(appId))
			{
				analyticsServiceInstance = Instances[appId];
			}
			else
			{
				analyticsServiceInstance = new AnalyticsServiceInstance(appId, null, config, mono);
				if (string.IsNullOrEmpty(CurrentAppid))
				{
					CurrentAppid = appId;
				}
				Instances[appId] = analyticsServiceInstance;
			}
			return analyticsServiceInstance;
		}

