		private void SendData(EventData data)
		{
			SendData(data, immediately: false);
		}

		private void SendData(EventData data, bool immediately)
		{
			if (mDynamicSuperProperties != null)
			{
				data.SetProperties(mDynamicSuperProperties.GetDynamicSuperProperties(), isOverwrite: false);
			}
			if (mSupperProperties != null && mSupperProperties.Count > 0)
			{
				data.SetProperties(mSupperProperties, isOverwrite: false);
			}
			Dictionary<string, object> deviceInfo = CommonUtil.GetDeviceInfo();
			if (!string.IsNullOrEmpty(deviceAdId))
			{
				deviceInfo["#device_ad_id"] = deviceAdId;
			}
			data.SetProperties(deviceInfo, isOverwrite: false);
			float num = 0f;
			if (mTimeEvents.ContainsKey(data.EventName()))
			{
				int num2 = (int)mTimeEvents[data.EventName()];
				num = (float)((double)(Environment.TickCount - num2) / 1000.0);
				mTimeEvents.Remove(data.EventName());
				if (mTimeEventsBefore.ContainsKey(data.EventName()))
				{
					int num3 = (int)mTimeEventsBefore[data.EventName()];
					num += (float)((double)num3 / 1000.0);
					mTimeEventsBefore.Remove(data.EventName());
				}
			}
			if (num != 0f)
			{
				data.SetDuration(num);
			}
			SendData((BaseData)data, immediately);
		}

		private void SendData(BaseData data)
		{
			SendData(data, immediately: false);
		}

		private void SendData(BaseData data, bool immediately)
		{
			if (IsPaused())
			{
				return;
			}
			if (!string.IsNullOrEmpty(mAccountID))
			{
				data.SetAccountID(mAccountID);
			}
			if (string.IsNullOrEmpty(mDistinctID))
			{
				DistinctId();
			}
			data.SetDistinctID(mDistinctID);
			if (mConfig.IsDisabledEvent(data.EventName()))
			{
				if (Log.GetEnable())
				{
					Log.i("Disabled Event: " + data.EventName());
				}
				return;
			}
			if (immediately)
			{
				Dictionary<string, object> obj = data.ToDictionary();
				mMono.StartCoroutine(AnalyticsRequest.SendData_2(null, MiniJson.Serialize(obj), 1));
				return;
			}
			Dictionary<string, object> dictionary = data.ToDictionary();
			int num = 0;
			if (!string.IsNullOrEmpty(mConfig.InstanceName()))
			{
				if (Log.GetEnable())
				{
					Log.i("Enqueue data: \n" + MiniJson.Serialize(dictionary) + "\n  AppId: " + mAppid);
				}
				num = FileJson.EnqueueReportingData(dictionary, mConfig.InstanceName());
			}
			else
			{
				if (Log.GetEnable())
				{
					Log.i("Enqueue data: \n" + MiniJson.Serialize(dictionary) + "\n  AppId: " + mAppid);
				}
				num = FileJson.EnqueueReportingData(dictionary, mAppid);
			}
			if (num >= mConfig.mUploadSize)
			{
				if (Log.GetEnable())
				{
					Log.i("Flush automatically (" + mAppid + ")");
				}
				Flush();
			}
		}

		private IEnumerator WaitAndFlush()
		{
			while (true)
			{
				yield return flushDelay;
				if (Log.GetEnable())
				{
					Log.i("Flush automatically (" + mAppid + ")");
				}
				Flush();
			}
		}

		public virtual void Flush()
		{
			if (!mEventSaveOnly)
			{
				mTask.SyncInvokeAllTask();
				int mUploadSize = mConfig.mUploadSize;
				if (!string.IsNullOrEmpty(mConfig.InstanceName()))
				{
					mTask.StartRequest(mRequest, EventResponseHandle, mUploadSize, mConfig.InstanceName());
				}
				else
				{
					mTask.StartRequest(mRequest, EventResponseHandle, mUploadSize, mAppid);
				}
			}
		}

