		protected bool IsPaused()
		{
			int num;
			if (mEnableReporting)
			{
				num = ((!mOptReporting) ? 1 : 0);
				if (num == 0)
				{
					goto IL_0028;
				}
			}
			else
			{
				num = 1;
			}
			if (Log.GetEnable())
			{
				Log.i("SDK Report status is Pause or Stop");
			}
			goto IL_0028;
			IL_0028:
			return (byte)num != 0;
		}

		public void SetReportStatus(ReportStatus status)
		{
			if (Log.GetEnable())
			{
				Log.i("Change Status to " + status);
			}
			switch (status)
			{
			case ReportStatus.Pause:
				mEventSaveOnly = false;
				OptReporting(optReporting: true);
				EnableReporting(isEnable: false);
				break;
			case ReportStatus.Stop:
				mEventSaveOnly = false;
				EnableReporting(isEnable: true);
				OptReporting(optReporting: false);
				break;
			case ReportStatus.SaveOnly:
				mEventSaveOnly = true;
				EnableReporting(isEnable: true);
				OptReporting(optReporting: true);
				break;
			default:
				mEventSaveOnly = false;
				OptReporting(optReporting: true);
				EnableReporting(isEnable: true);
				Flush();
				break;
			}
		}

		public void OptReporting(bool optReporting)
