				Unity.UOS.Insight.Utils.File.DeleteData(mAppid, "#distinct_id");
				Unity.UOS.Insight.Utils.File.DeleteData(mAppid, "super_properties");
				mAccountID = null;
				mDistinctID = null;
				mSupperProperties = new Dictionary<string, object>();
				FileJson.DeleteAllReportingData(mAppid);
			}
		}

