	public class NTPCalibration : TimeCalibration
	{
		public NTPCalibration(string ntpServer)
		{
			double num = ConvertDateTimeInt(DateTime.UtcNow);
			mStartTime = (long)num;
			mSystemElapsedRealtime = Environment.TickCount;
			Socket networkTimeSync = GetNetworkTimeSync(ntpServer, this);
			InsightTimeout.SetTimeout(3, ScoketTimeout, networkTimeSync);
		}

		private void ScoketTimeout(object obj)
		{
			if (obj is Socket)
			{
				Socket socket = (Socket)obj;
				if (socket.Connected)
				{
					socket.Close();
				}
			}
		}

		protected new static double ConvertDateTimeInt(DateTime time)
		{
			DateTime dateTime = new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc);
			return (time - dateTime).TotalMilliseconds;
		}

		private static Socket GetNetworkTimeSync(string ntpServer, TimeCalibration timeCalibration)
		{
			byte[] array = new byte[48];
			array[0] = 27;
			IPAddress[] addressList = Dns.GetHostEntry(ntpServer).AddressList;
			IPAddress iPAddress = addressList.First((IPAddress iPAddress2) => iPAddress2.AddressFamily == AddressFamily.InterNetwork);
			if (iPAddress == null)
			{
				iPAddress = addressList[0];
			}
			IPEndPoint iPEndPoint = new IPEndPoint(iPAddress, 123);
			Socket socket = new Socket(iPEndPoint.AddressFamily, SocketType.Dgram, ProtocolType.Udp);
			socket.Connect(iPEndPoint);
			SocketAsyncEventArgs e = new SocketAsyncEventArgs();
			e.SetBuffer(array, 0, array.Length);
			e.UserToken = timeCalibration;
			e.RemoteEndPoint = iPEndPoint;
			e.Completed += SocketAsyncEventArgs_Completed;
			socket.SendAsync(e);
			return socket;
		}

		private static void SocketAsyncEventArgs_Completed(object sender, SocketAsyncEventArgs eventArgs)
		{
			Socket socket = (Socket)sender;
			if (eventArgs.SocketError == SocketError.Success)
			{
				if (eventArgs.LastOperation == SocketAsyncOperation.Send)
				{
					socket.ReceiveAsync(eventArgs);
				}
				else if (eventArgs.LastOperation == SocketAsyncOperation.Receive)
				{
					if (eventArgs.SocketError == SocketError.Success && eventArgs.Buffer.Length != 0)
					{
						double num = ConvertDateTimeInt(ParseDateTimeWithNTPData(eventArgs.Buffer));
						((TimeCalibration)eventArgs.UserToken).mStartTime = (long)num;
					}
					socket.Close();
				}
				else
				{
					socket.Close();
				}
			}
			else
			{
				socket.Close();
			}
		}

		private static uint SwapEndianness(ulong x)
		{
			return (uint)(((x & 0xFF) << 24) + ((x & 0xFF00) << 8) + ((x & 0xFF0000) >> 8) + ((x & 0xFF000000u) >> 24));
		}

		private static DateTime ParseDateTimeWithNTPData(byte[] ntpData)
		{
			ulong x = BitConverter.ToUInt32(ntpData, 40);
			ulong x2 = BitConverter.ToUInt32(ntpData, 44);
			ulong num = SwapEndianness(x);
			x2 = SwapEndianness(x2);
			ulong num2 = num * 1000 + x2 * 1000 / 4294967296L;
			return new DateTime(1900, 1, 1, 0, 0, 0, DateTimeKind.Utc).AddMilliseconds((long)num2);
		}
	}
