		private Dictionary<string, object> EncodeDate(Dictionary<string, object> properties)
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			foreach (KeyValuePair<string, object> property in properties)
			{
				if (property.Value is DateTime)
				{
					DateTime dateTime = (DateTime)property.Value;
					dictionary.Add(property.Key, dateTime.ToString("yyyy-MM-dd HH:mm:ss.fff", CultureInfo.InvariantCulture));
				}
				else
				{
					dictionary.Add(property.Key, property.Value);
				}
			}
			return dictionary;
		}
	}
	public class TimeCalibration
	{
		public long mStartTime;

		public long mSystemElapsedRealtime;

		public DateTime NowDate()
		{
			long num = Environment.TickCount - mSystemElapsedRealtime + mStartTime;
			return new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc).AddMilliseconds(num);
		}

		protected static double ConvertDateTimeInt(DateTime time)
		{
			DateTime dateTime = new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc);
			return (time - dateTime).TotalMilliseconds;
		}
	}
