		{
			DateTime utcNow = DateTime.UtcNow;
			mStartTime = timestamp;
			mSystemElapsedRealtime = Environment.TickCount;
			double num = (TimeCalibration.ConvertDateTimeInt(utcNow) - (double)timestamp) / 1000.0;
			if (Log.GetEnable())
			{
				Log.i("Time Calibration with NTP (" + timestamp + "), diff = " + num.ToString("0.000s"));
			}
		}
