			return mDisableEvents.Contains(eventName);
		}
	}
}
namespace Unity.UOS.Exceptions
{
	public class ExceptionUtil<TClientException, TServerException> where TClientException : Exception where TServerException : Exception
	{
		public static readonly Action<UnityWebRequest> ExceptionHandler = (UnityWebRequest request) =>
		{
			//IL_00fb: Unknown result type (might be due to invalid IL or missing references)
			//IL_0100: Unknown result type (might be due to invalid IL or missing references)
			//IL_0102: Unknown result type (might be due to invalid IL or missing references)
			//IL_0105: Unknown result type (might be due to invalid IL or missing references)
			//IL_0117: Expected I4, but got Unknown
			try
			{
				object value;
				if (request == null)
				{
					value = null;
				}
				else
				{
					DownloadHandler downloadHandler = request.downloadHandler;
					value = ((downloadHandler != null) ? downloadHandler.text : null);
				}
				if (string.IsNullOrEmpty((string?)value))
				{
					if (!string.IsNullOrEmpty((request != null) ? request.error : null))
					{
						Result result = request.result;
						switch (result - 2)
						{
						case 0:
							throw (TClientException)Activator.CreateInstance(typeof(TClientException), ErrorCode.NetworkError, "Network connection error: " + request.error, null);
						case 2:
							throw (TClientException)Activator.CreateInstance(typeof(TClientException), ErrorCode.Unknown, "Data processing error: " + request.error, null);
						case 1:
							throw (TServerException)Activator.CreateInstance(typeof(TServerException), ErrorCode.Unknown, "Protocol error: " + request.error);
						default:
							Debug.LogErrorFormat("occurred unexpected error when send http request, url: {0}, method: {1}. err: {2}", new object[3] { request.url, request.method, request.error });
							throw (TClientException)Activator.CreateInstance(typeof(TClientException), ErrorCode.Unknown, "Request failed: " + request.error, null);
						}
					}
					throw (TClientException)Activator.CreateInstance(typeof(TClientException), ErrorCode.Unknown, "Request failed without specific error information", null);
				}
				UosServiceError uosServiceError = JsonConvert.DeserializeObject<UosServiceError>(request.downloadHandler.text);
				if (request.responseCode >= 500)
				{
					throw (TServerException)Activator.CreateInstance(typeof(TServerException), ErrorCode.Unknown, uosServiceError.ToString(), null);
				}
				long responseCode = request.responseCode;
				long num = responseCode - 401;
				if ((ulong)num > 3uL)
				{
					goto IL_00ae;
				}
				switch ((int)num)
				{
				case 0:
					break;
				case 2:
					goto IL_00a6;
				case 3:
					goto IL_00aa;
				default:
					goto IL_00ae;
				}
				ErrorCode errorCode = ErrorCode.InvalidToken;
				goto IL_00b0;
				IL_00ae:
				errorCode = ErrorCode.InvalidRequest;
				goto IL_00b0;
				IL_00a6:
				errorCode = ErrorCode.Forbidden;
				goto IL_00b0;
				IL_00b0:
				ErrorCode errorCode2 = errorCode;
				throw (TClientException)Activator.CreateInstance(typeof(TClientException), errorCode2, uosServiceError.ToString(), null);
				IL_00aa:
				errorCode = ErrorCode.NotFound;
				goto IL_00b0;
			}
			catch (Exception ex) when (!(ex is TClientException) && !(ex is TServerException))
			{
				Debug.LogErrorFormat("occurred unexpected exception when send http request, url: {0}, method: {1}, ex: {2}", new object[3]
				{
					(request != null) ? request.url : null,
					(request != null) ? request.method : null,
					ex
				});
				throw (TServerException)Activator.CreateInstance(typeof(TServerException), ErrorCode.Unknown, ex.Message, ex);
			}
		};
	}
	public enum ErrorCode
	{
		Unknown,
		Timeout,
		ServiceUnavailable,
		RequestRejected,
		InvalidToken,
		TokenExpired,
		Forbidden,
		NotFound,
		InvalidRequest,
		NetworkError
	}
}
namespace Unity.UOS.Auth
{
	public class AuthTokenManager : GenericSingleton<AuthTokenManager>
	{
		private static readonly TimeSpan RefreshGracePeriod = TimeSpan.FromMinutes(10.0);

		private const string IdDomainPublicInfoPath = "/v1/sdk/id-domains/{0}/public-info";

		private const string ExternalLoginPath = "/v1/login/external";

		private const string GenerateTokenPath = "/v1/login/token";

		private const string PassportRefreshPath = "/v1/sdk/personas/refresh-token";

		private const string NonPassportRefreshPath = "/v1/login/refresh-token";

		private const string IdDomainNotFoundError = "未找到Id Domain";

		private static readonly Mutex InitMutex = new Mutex();

		private static readonly Mutex RefreshMutex = new Mutex();

		private static bool _refreshing = false;

		private const string SdkName = "Auth-Token-Manager";

		private const string SdkVersion = "2.9.0";

		private readonly Dictionary<string, AppSetting> _appSettings = new Dictionary<string, AppSetting>();

		public string CurrentUosAppID { get; set; }

		public static void Initialize(string uosAppID, string uosAppSecret)
		{
			Initialize(new InitOptions(uosAppID, uosAppSecret));
		}

		public static void Initialize(InitOptions options)
		{
			InitMutex.WaitOne();
			try
			{
				if (GenericSingleton<AuthTokenManager>.Instance._appSettings.TryGetValue(options.UosAppID, out var value))
				{
					value.UosAppID = options.UosAppID;
					if (value.UosAppSecret != options.UosAppSecret)
					{
						value.UosAppSecret = options.UosAppSecret;
						value.TokenInfo = null;
						value.HttpClient = new HttpClient(new HttpClientOptions
						{
							SdkName = "Auth-Token-Manager",
							SdkVersion = "2.9.0",
							BaseUrl = Endpoints.PassportEndpoint,
							Authenticator = new UosNonceAuthenticator(options.UosAppID, options.UosAppSecret),
							ExceptionHandler = ExceptionUtil.ExceptionHandler,
							Timeout = options.HttpClientTimeout
						});
					}
					value.TokenPersistKey = "passport:current_token:" + options.UosAppID;
				}
				else
				{
					value = new AppSetting
					{
						UosAppID = options.UosAppID,
						UosAppSecret = options.UosAppSecret,
						TokenPersistKey = "passport:current_token:" + options.UosAppID,
						HttpClient = new HttpClient(new HttpClientOptions
						{
							SdkName = "Auth-Token-Manager",
							SdkVersion = "2.9.0",
							BaseUrl = Endpoints.PassportEndpoint,
							Authenticator = new UosNonceAuthenticator(options.UosAppID, options.UosAppSecret),
							ExceptionHandler = ExceptionUtil.ExceptionHandler,
							Timeout = options.HttpClientTimeout
						})
					};
					GenericSingleton<AuthTokenManager>.Instance._appSettings[options.UosAppID] = value;
				}
				GenericSingleton<AuthTokenManager>.Instance.CurrentUosAppID = options.UosAppID;
				InsightSDK.Initialize();
			}
			finally
			{
				InitMutex.ReleaseMutex();
			}
		}

		[Obsolete("InitializeAsync已弃用，请使用Initialize(string uosAppID, string uosAppSecret)")]
		public static async System.Threading.Tasks.Task InitializeAsync(string uosAppID, string uosAppSecret)
		{
			Initialize(uosAppID, uosAppSecret);
		}

		[Obsolete("Initialize已弃用，请使用Initialize(string uosAppID, string uosAppSecret)")]
		public static void Initialize(string uosAppID, string uosAppSecret, bool usePassportIdentity)
		{
			Initialize(uosAppID, uosAppSecret);
		}

		public static void SaveToken(string uosAppID, TokenInfo token)
		{
			if (!GenericSingleton<AuthTokenManager>.Instance._appSettings.ContainsKey(uosAppID))
			{
				throw new AuthException(ErrorCode.InvalidUosAppID, "无效的UosAppID");
			}
			AppSetting appSetting = GenericSingleton<AuthTokenManager>.Instance._appSettings[uosAppID];
			appSetting.TokenInfo = token;
			PersistManager.SetString(value: JsonConvert.SerializeObject((object)appSetting.TokenInfo), key: appSetting.TokenPersistKey);
			Dictionary<string, object> dictionary = new Dictionary<string, object> { ["login_session_id"] = Guid.NewGuid().ToString() };
			string account;
			if (string.IsNullOrEmpty(token.PersonaId))
			{
				account = token.UserId;
			}
			else
			{
				account = token.PersonaId;
				dictionary["passport_user_id"] = token.UserId;
			}
			InsightSDK.SetSuperProperties(dictionary);
			InsightSDK.Login(account);
		}

		public static void SaveToken(TokenInfo token)
		{
			if (string.IsNullOrEmpty(GenericSingleton<AuthTokenManager>.Instance.CurrentUosAppID))
			{
				throw new AuthException(ErrorCode.NotInitialized, "AuthTokenManager未经初始化");
			}
			SaveToken(GenericSingleton<AuthTokenManager>.Instance.CurrentUosAppID, token);
		}

		public static void ClearToken()
		{
			ClearToken(GenericSingleton<AuthTokenManager>.Instance.CurrentUosAppID);
		}

		public static void ClearToken(string uosAppID)
		{
			if (GenericSingleton<AuthTokenManager>.Instance._appSettings.ContainsKey(uosAppID))
			{
				AppSetting appSetting = GenericSingleton<AuthTokenManager>.Instance._appSettings[uosAppID];
				appSetting.TokenInfo = null;
				PersistManager.DeleteKey(appSetting.TokenPersistKey);
			}
			else
			{
				Debug.Log((object)("UOS App " + uosAppID + " not found, ClearToken ignored."));
			}
		}

		public static async Task<TokenInfo> GetTokenInfo(string uosAppID)
		{
			if (!GenericSingleton<AuthTokenManager>.Instance._appSettings.ContainsKey(uosAppID))
			{
				throw new AuthException(ErrorCode.InvalidUosAppID, "无效的UosAppID");
			}
			AppSetting currentAppSetting = GenericSingleton<AuthTokenManager>.Instance._appSettings[uosAppID];
			if (currentAppSetting.TokenInfo == null)
			{
				string text = PersistManager.GetString(currentAppSetting.TokenPersistKey, "");
				if (string.IsNullOrEmpty(text))
				{
					throw new AuthException(ErrorCode.NeedLogin, "需要重新登录以获取新的AccessToken/RefreshToken");
				}
				currentAppSetting.TokenInfo = JsonConvert.DeserializeObject<TokenInfo>(text);
			}
			JsonWebToken jwt = JsonWebToken.Decode(currentAppSetting.TokenInfo.AccessToken);
			DateTime now = DateTime.UtcNow;
			if (now > jwt.Expiration)
			{
				RefreshMutex.WaitOne();
				try
				{
					await AsyncRefreshAccessToken(uosAppID);
				}
				finally
				{
					RefreshMutex.ReleaseMutex();
				}
			}
			if (now > jwt.Expiration - RefreshGracePeriod && !_refreshing && RefreshMutex.WaitOne(0, exitContext: true))
			{
				try
				{
					if (!_refreshing)
					{
						((MonoBehaviour)GenericSingleton<AuthTokenManager>.Instance).StartCoroutine(RefreshAccessToken(uosAppID));
					}
				}
				finally
				{
					RefreshMutex.ReleaseMutex();
				}
			}
			return currentAppSetting.TokenInfo;
		}

		public static async Task<TokenInfo> GetTokenInfo()
		{
			if (string.IsNullOrEmpty(GenericSingleton<AuthTokenManager>.Instance.CurrentUosAppID))
			{
				throw new AuthException(ErrorCode.NotInitialized, "AuthTokenManager未经初始化");
			}
			return await GetTokenInfo(GenericSingleton<AuthTokenManager>.Instance.CurrentUosAppID);
		}

		public static async Task<string> GetAccessToken(string uosAppID)
		{
			return (await GetTokenInfo(uosAppID)).AccessToken;
		}

		public static async Task<string> GetAccessToken()
		{
			if (string.IsNullOrEmpty(GenericSingleton<AuthTokenManager>.Instance.CurrentUosAppID))
			{
				throw new AuthException(ErrorCode.NotInitialized, "AuthTokenManager未经初始化");
			}
			return await GetAccessToken(GenericSingleton<AuthTokenManager>.Instance.CurrentUosAppID);
		}

		public static async Task<TokenInfo> ExternalLogin(string userID, string personaID = null, string displayName = null, string realmID = null, string channel = null)
		{
			if (string.IsNullOrEmpty(GenericSingleton<AuthTokenManager>.Instance.CurrentUosAppID))
			{
				throw new AuthException(ErrorCode.NotInitialized, "AuthTokenManager未经初始化");
			}
			return await ExternalLoginWithAppId(GenericSingleton<AuthTokenManager>.Instance.CurrentUosAppID, userID, personaID, displayName, realmID, channel);
		}

		public static async Task<TokenInfo> ExternalLoginWithAppId(string uosAppID, string userID, string personaID, string displayName = null, string realmID = null, string channel = null)
		{
			return await ExternalLogin(new ExternalLoginRequest
			{
				uosAppID = uosAppID,
				externalUserID = userID,
				externalPersonaID = personaID,
				displayName = displayName,
				realmID = realmID,
				channel = channel
			});
		}

		public static async Task<TokenInfo> ExternalLogin(ExternalLoginRequest request)
		{
			string uosAppID = request.uosAppID;
			if (string.IsNullOrEmpty(uosAppID))
			{
				uosAppID = GenericSingleton<AuthTokenManager>.Instance.CurrentUosAppID;
			}
			if (!GenericSingleton<AuthTokenManager>.Instance._appSettings.ContainsKey(uosAppID))
			{
				throw new AuthException(ErrorCode.InvalidUosAppID, "无效的UosAppID");
			}
			AppSetting currentAppSetting = GenericSingleton<AuthTokenManager>.Instance._appSettings[uosAppID];
			string data = JsonConvert.SerializeObject((object)request);
			ExternalLoginResponse externalLoginResponse = await currentAppSetting.HttpClient.Post<ExternalLoginResponse>("/v1/login/external", data);
			currentAppSetting.TokenInfo = new TokenInfo
			{
				AccessToken = externalLoginResponse.personaAccessToken,
				RefreshToken = externalLoginResponse.personaRefreshToken,
				UserId = ((externalLoginResponse.persona == null) ? request.externalUserID : externalLoginResponse.persona.userID),
				UserName = request.displayName,
				AccessTokenExpiresAt = JsonWebToken.Decode(externalLoginResponse.personaAccessToken).Expiration,
				RefreshTokenExpiresAt = JsonWebToken.Decode(externalLoginResponse.personaRefreshToken).Expiration,
				IsNew = externalLoginResponse.isNew,
				PersonaId = ((externalLoginResponse.persona == null) ? request.externalPersonaID : externalLoginResponse.persona.personaID)
			};
			SaveToken(uosAppID, currentAppSetting.TokenInfo);
			return currentAppSetting.TokenInfo;
		}

		public static async System.Threading.Tasks.Task GenerateAccessTokenWithUosAppId(string uosAppID, string userID, string userName = "")
		{
			if (!GenericSingleton<AuthTokenManager>.Instance._appSettings.ContainsKey(uosAppID))
			{
				throw new AuthException(ErrorCode.InvalidUosAppID, "无效的UosAppID");
			}
			AppSetting currentAppSetting = GenericSingleton<AuthTokenManager>.Instance._appSettings[uosAppID];
			string data = JsonConvert.SerializeObject((object)new GenerateAccessTokenRequest
			{
				userID = userID
			});
			GetAccessTokenResponse getAccessTokenResponse = await currentAppSetting.HttpClient.Post<GetAccessTokenResponse>("/v1/login/token", data);
			currentAppSetting.TokenInfo = new TokenInfo
			{
				AccessToken = getAccessTokenResponse.accessToken,
				RefreshToken = getAccessTokenResponse.refreshToken,
				UserId = userID,
				UserName = userName
			};
			SaveToken(uosAppID, currentAppSetting.TokenInfo);
		}

		public static async System.Threading.Tasks.Task GenerateAccessToken(string userID, string userName = "")
		{
			if (string.IsNullOrEmpty(GenericSingleton<AuthTokenManager>.Instance.CurrentUosAppID))
			{
				throw new AuthException(ErrorCode.NotInitialized, "AuthTokenManager未经初始化");
			}
			await GenerateAccessTokenWithUosAppId(GenericSingleton<AuthTokenManager>.Instance.CurrentUosAppID, userID, userName);
		}

		public static async Task<TokenInfo> AsyncRefreshAccessToken()
		{
			return await AsyncRefreshAccessToken(GenericSingleton<AuthTokenManager>.Instance.CurrentUosAppID);
		}

		public static async Task<TokenInfo> AsyncRefreshAccessToken(string uosAppID)
		{
			try
			{
				_refreshing = true;
				AppSetting currentAppSetting = GenericSingleton<AuthTokenManager>.Instance._appSettings[uosAppID];
				TokenInfo currentTokenInfo = currentAppSetting.TokenInfo;
				if (JsonWebToken.Decode(currentTokenInfo.RefreshToken).Expiration < DateTime.UtcNow)
				{
					throw new AuthException(ErrorCode.NeedLogin, "需要重新登录以获取新的AccessToken/RefreshToken");
				}
				long localTimestamp = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
				string data = JsonConvert.SerializeObject((object)new RefreshTokenRequest
				{
					accessToken = currentTokenInfo.AccessToken,
					refreshToken = currentTokenInfo.RefreshToken,
					localTimestamp = localTimestamp
				});
				string url = "/v1/sdk/personas/refresh-token";
				GetAccessTokenResponse getAccessTokenResponse = await currentAppSetting.HttpClient.Post<GetAccessTokenResponse>(url, data);
				currentAppSetting.TokenInfo = new TokenInfo
				{
					AccessToken = getAccessTokenResponse.accessToken,
					RefreshToken = getAccessTokenResponse.refreshToken,
					UserId = currentTokenInfo.UserId,
					UserName = currentTokenInfo.UserName,
					PersonaId = currentTokenInfo.PersonaId,
					AccessTokenExpiresAt = JsonWebToken.Decode(getAccessTokenResponse.accessToken).Expiration,
					RefreshTokenExpiresAt = JsonWebToken.Decode(getAccessTokenResponse.refreshToken).Expiration,
					IsNew = false
				};
				SaveToken(currentAppSetting.TokenInfo);
				return currentAppSetting.TokenInfo;
			}
			finally
			{
				_refreshing = false;
			}
		}

		private static IEnumerator RefreshAccessToken()
		{
			return RefreshAccessToken(GenericSingleton<AuthTokenManager>.Instance.CurrentUosAppID);
		}

		private static IEnumerator RefreshAccessToken(string uosAppID)
		{
			Task<TokenInfo> task = AsyncRefreshAccessToken(uosAppID);
			yield return (object)new WaitUntil((Func<bool>)(() => task.IsCompleted));
		}
	}
