	public struct JsonWebToken
	{
		private static readonly char[] JwtSeparator = new char[1] { '.' };

		public static readonly DateTime UnixEpoch = new DateTime(1970, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc);

		public DateTime Expiration { get; }

		public string UserID { get; }

		public string PersonaID { get; }

		[JsonConstructor]
		public JsonWebToken(long exp, string userID, string personaID)
		{
			DateTime unixEpoch = UnixEpoch;
			Expiration = unixEpoch.AddSeconds(exp);
			UserID = userID;
			PersonaID = personaID;
		}

		public override string ToString()
		{
			return JsonConvert.SerializeObject((object)this);
		}

		public static JsonWebToken Decode(string token)
		{
			string[] array = token.Split(JwtSeparator);
			if (array.Length != 3)
			{
				throw new AuthException(ErrorCode.InvalidJwt, "invalid jwt");
			}
			string input = array[1];
			Payload payload = JsonConvert.DeserializeObject<Payload>(Encoding.UTF8.GetString(Base64UrlDecode(input)));
			return new JsonWebToken(payload.exp, payload.sub, payload.ppid);
		}

		private static byte[] Base64UrlDecode(string input)
		{
			string text = input;
			text = text.Replace('-', '+');
			text = text.Replace('_', '/');
			int num = input.Length % 4;
			if (num > 0)
			{
				text += new string('=', 4 - num);
			}
			return Convert.FromBase64String(text);
		}
	}
	[Serializable]
	internal struct Payload
	{
		public int exp;

		public string sub;

		public string ppid;
	}
