		{
			Debug.LogWarning((object)"Encryption method is not currently being used. Please click 【UOS -> Launcher -> Import Package Resources】 to import encryption method, which increase security.");
		}

		public static string GetValue(string key, string defaultValue = null)
		{
			ConfigPair[] array = Instance.configPairs;
			foreach (ConfigPair configPair in array)
			{
				if (configPair.key == key)
				{
					return configPair.value;
				}
			}
			return defaultValue;
		}
