namespace Unity.UOS.Common.UOSLauncher.Scripts.Auth
{
	public enum ErrorCode
	{
		NotInitialized,
		InvalidUosAppID,
		InvalidJwt,
		NeedLogin,
		RefreshFailed,
		GenerateTokenFailed,
		NonceTimestampExpired,
		InvalidOperation,
		PlayerBanned,
		Unknown
	}
	public class ErrorDetailBase
	{
	}
	public class PersonaBannedDetail : ErrorDetailBase
	{
		public string BanReason;

		public string PersonaID;

		public string PersonaDisplayName;

		public DateTime? UnbanAt;
	}
	public class AuthException : Exception
	{
		public ErrorCode ErrorCode { get; }

		public Dictionary<string, string> ErrorDetail { get; }

		public ErrorDetailBase DetailInfo { get; }

		public AuthException(ErrorCode errorCode, string message)
			: base(message)
		{
			ErrorCode = errorCode;
		}

		public AuthException(ErrorCode errorCode, string message, Dictionary<string, string> detail)
			: base(message)
		{
			ErrorCode = errorCode;
			ErrorDetail = detail;
			DetailInfo = ParseErrorDetail(errorCode, detail);
		}

		private static ErrorDetailBase ParseErrorDetail(ErrorCode errorCode, Dictionary<string, string> detail)
		{
			if (errorCode == ErrorCode.PlayerBanned)
			{
				return ParseBannedDetail(detail);
			}
			return new ErrorDetailBase();
		}

		private static PersonaBannedDetail ParseBannedDetail(Dictionary<string, string> detail)
		{
			PersonaBannedDetail personaBannedDetail = new PersonaBannedDetail();
			if (detail.TryGetValue("BanReason", out var value))
			{
				personaBannedDetail.BanReason = value;
			}
			if (detail.TryGetValue("UnbanAt", out var value2) && DateTime.TryParse(value2, out var result))
			{
				personaBannedDetail.UnbanAt = result;
			}
			if (detail.TryGetValue("PersonaDisplayName", out var value3))
			{
				personaBannedDetail.PersonaDisplayName = value3;
			}
			if (detail.TryGetValue("PersonaID", out var value4))
			{
				personaBannedDetail.PersonaID = value4;
			}
			return personaBannedDetail;
		}
	}
	public class ExceptionUtil
	{
		private const string NonceTokenExpired = "nonce timestamp expired";

		private const int ErrorCodeUserBanned = 90108;

		private const int ErrorCodePersonaBanned = 90109;

		private const int ErrorCodeRefreshTokenExpired = 160113;

		public static readonly Action<UnityWebRequest> ExceptionHandler = (UnityWebRequest request) =>
		{
			UosAuthError uosAuthError;
			try
			{
				uosAuthError = JsonConvert.DeserializeObject<UosAuthError>(request.downloadHandler.text);
			}
			catch (Exception ex)
			{
				Debug.LogException(ex);
				throw new AuthException(ErrorCode.Unknown, request.downloadHandler.text);
			}
			Debug.LogError((object)$"Passport Error: {uosAuthError}");
			if ("nonce timestamp expired".Equals(uosAuthError.message))
			{
				throw new AuthException(ErrorCode.NonceTimestampExpired, uosAuthError.message);
			}
			switch (uosAuthError.detailCode)
			{
			case 90108:
			case 90109:
				throw new AuthException(ErrorCode.PlayerBanned, uosAuthError.message, uosAuthError.detailInfo);
			case 160113:
				throw new AuthException(ErrorCode.NeedLogin, uosAuthError.message);
			default:
				throw new AuthException(ErrorCode.GenerateTokenFailed, uosAuthError.message);
			}
		};
	}
	[Serializable]
	public class UosAuthError : UosServiceError
	{
		[JsonProperty(PropertyName = "passportErrorCode")]
		public int detailCode;

		[JsonProperty(PropertyName = "passportErrorDetail")]
		public Dictionary<string, string> detailInfo;
	}
}
